```typescript
import { User, UserRole } from '../types';
import { MOCK_USERS } from '../constants';

// Extending User interface locally to include password for simulation
interface UserWithPassword extends User {
  password?: string;
}

const USERS_STORAGE_KEY = 'eledger_users';

export const AuthService = {
  // Initialize with mock users if empty
  getUsers: (): UserWithPassword[] => {
    const stored = localStorage.getItem(USERS_STORAGE_KEY);
    if (!stored) {
      // Seed with mock users, default password is 'password'
      const initialUsers: UserWithPassword[] = MOCK_USERS.map(u => ({ ...u, password: 'password' }));
      localStorage.setItem(USERS_STORAGE_KEY, JSON.stringify(initialUsers));
      return initialUsers;
    }
    return JSON.parse(stored);
  },

  generateGLN: (): string => {
    // Generate a valid 13-digit GLN using GS1 Mod-10 Checksum
    // 1. Generate 12 digits (Prefix '049' + 9 random)
    const prefix = '049';
    const randomPart = Math.floor(Math.random() * 1000000000).toString().padStart(9, '0');
    const data = prefix + randomPart;

    // 2. Calculate Check Digit
    // Algorithm: Sum of (digit * weight). Weights alternate 1 and 3.
    let sum = 0;
    for (let i = 0; i < data.length; i++) {
      const digit = parseInt(data[i]);
      // GS1 Weights for GTIN-13/GLN: 
      // Positions are 1-based from left.
      // Odd positions (1, 3, 5...) have weight 1.
      // Even positions (2, 4, 6...) have weight 3.
      // Since 'i' is 0-based index: i=0 is Pos 1 (Weight 1), i=1 is Pos 2 (Weight 3).
      const weight = i % 2 === 0 ? 1 : 3;
      sum += digit * weight;
    }

    const nearestTen = Math.ceil(sum / 10) * 10;
    const checkDigit = nearestTen - sum;

    return data + checkDigit;
  },

  login: async (gln: string, password: string): Promise<User | null> => {
    // Simulate network delay
    await new Promise(resolve => setTimeout(resolve, 600));

    const users = AuthService.getUsers();
    const user = users.find(u => u.gln === gln && u.password === password);

    if (user) {
      // Return user without password
      const { password: _, ...safeUser } = user;
      return safeUser;
    }
    return null;
  },

  signup: async (name: string, orgName: string, gln: string, role: UserRole, password: string): Promise<User> => {
    await new Promise(resolve => setTimeout(resolve, 800));

    const users = AuthService.getUsers();

    if (users.find(u => u.gln === gln)) {
      throw new Error('A user with this GLN already exists.');
    }

    const newUser: UserWithPassword = {
      id: `user-${Date.now()}`,
      name,
      orgName,
      gln,
      role,
      password
    };

    users.push(newUser);
    localStorage.setItem(USERS_STORAGE_KEY, JSON.stringify(users));

    const { password: _, ...safeUser } = newUser;
    return safeUser;
  }
};
```

