        throw new Error('GLN must be exactly 13 digits.');
      }

      await AuthService.signup(
        formData.name,
        formData.orgName,
        formData.gln,
        formData.role,
        formData.password
      );

      // Auto redirect to login after signup
      navigate('/login');
    } catch (err: any) {
      setError(err.message || 'Failed to register.');
