import React, { useState, useEffect } from 'react';
import { HashRouter as Router, Routes, Route, Navigate } from 'react-router-dom';
import Layout from './components/Layout';
import Dashboard from './components/Dashboard';
import BatchManager from './components/BatchManager';
import TraceVisualizer from './components/TraceVisualizer';
import Assistant from './components/Assistant';
import Login from './components/Login';
import Signup from './components/Signup';
import UserProfile from './components/UserProfile';
import { getCurrentUser, login, logout } from './utils/authUtils';

function App() {
  const [currentUser, setCurrentUser] = useState(getCurrentUser());

  useEffect(() => {
    const handleStorageChange = (e: StorageEvent) => {
      if (e.key === 'currentUser') {
        setCurrentUser(getCurrentUser());
      }
    };
    window.addEventListener('storage', handleStorageChange);
    return () => window.removeEventListener('storage', handleStorageChange);
  }, []);

  const handleLogin = (user: any) => {
    login(user);
    setCurrentUser(user);
  };

  const handleLogout = () => {
    logout();
    setCurrentUser(null);
  };

  return (
    <Router>
      <Routes>
        <Route path="/login" element={<Login onLogin={handleLogin} />} />
        <Route path="/signup" element={<Signup />} />
        {currentUser ? (
          <Route path="/" element={<Layout currentUser={currentUser} onLogout={handleLogout} />}>
            <Route index element={<Dashboard />} />
            <Route path="batch-manager" element={<BatchManager />} />
            <Route path="trace-visualizer" element={<TraceVisualizer />} />
            <Route path="assistant" element={<Assistant />} />
            <Route path="user-profile" element={<UserProfile />} />
          </Route>
        ) : (
          <Route path="*" element={<Navigate to="/login" />} />
        )}
      </Routes>
    </Router>
  );
}

export default App;
```


