  getUsers: (): UserWithPassword[] => {
    const stored = localStorage.getItem(USERS_STORAGE_KEY);

    if (!stored) {
      // If MOCK_USERS is empty (production mode), initialize empty array
      const initialUsers: UserWithPassword[] = MOCK_USERS.map(u => ({ ...u, password: 'password' }));
      localStorage.setItem(USERS_STORAGE_KEY, JSON.stringify(initialUsers));
      return initialUsers;
    }

    try {
      const parsedUsers: UserWithPassword[] = JSON.parse(stored);

      // SELF-HEALING: Check if legacy data exists (users without passwords)
      const hasStaleData = parsedUsers.some(u => !u.password);

      if (hasStaleData) {
        // Patch missing passwords with default to prevent login lockouts
        const fixedUsers = parsedUsers.map(u => ({
          ...u,
          password: u.password || 'password'
        }));
        localStorage.setItem(USERS_STORAGE_KEY, JSON.stringify(fixedUsers));
        return fixedUsers;
      }

      return parsedUsers;
    } catch (e) {
      console.error("User storage corrupted, resetting.", e);
      const initialUsers: UserWithPassword[] = MOCK_USERS.map(u => ({ ...u, password: 'password' }));
      localStorage.setItem(USERS_STORAGE_KEY, JSON.stringify(initialUsers));
      return initialUsers;
    }
  },

  /**
   * Validates a GS1 Identifier (GTIN-8, GTIN-12, GTIN-13, GTIN-14, GLN, SSCC)
   * utilizing the standard Modulo-10 algorithm.
   */
  validateGS1: (code: string): boolean => {
    if (!code || !/^\d+$/.test(code)) return false;

    // GS1 keys are typically 8, 12, 13, 14, or 18 digits
    if (![8, 12, 13, 14, 18].includes(code.length)) return false;

    const digits = code.split('').map(Number);
    const checkDigit = digits.pop()!;
    const inputDigits = digits.reverse();

    let sum = 0;
    for (let i = 0; i < inputDigits.length; i++) {
      // Weight is 3 for even positions (0-index based from right, so actually odd pos from right)
      // Weight is 1 for odd positions
      // Standard: alternating 3 and 1 starting from the rightmost non-check digit.
      const weight = i % 2 === 0 ? 3 : 1;
      sum += inputDigits[i] * weight;
    }

    const nearestTen = Math.ceil(sum / 10) * 10;
    const calculatedCheckDigit = nearestTen - sum;

    return calculatedCheckDigit === checkDigit;
  },

  generateGLN: (): string => {
    // Generate a valid 13-digit GLN using GS1 Mod-10 Checksum
    // 1. Generate 12 digits (Prefix '049' + 9 random)
    const prefix = '049';
    const randomPart = Math.floor(Math.random() * 1000000000).toString().padStart(9, '0');
    const data = prefix + randomPart;

    // 2. Calculate Check Digit
    let sum = 0;
    for (let i = 0; i < data.length; i++) {
      const digit = parseInt(data[i]);
      const weight = i % 2 === 0 ? 1 : 3;
      sum += digit * weight;
    }

    const nearestTen = Math.ceil(sum / 10) * 10;
    const checkDigit = nearestTen - sum;

    return data + checkDigit;
  },

  generateGTIN: (): string => {
    // Generate a valid 14-digit GTIN
    // 1. Generate 13 digits (Prefix '0' + 12 random)
    const prefix = '0'; 
    const randomPart = Math.floor(Math.random() * 1000000000000).toString().padStart(12, '0');
    const data = prefix + randomPart;

    // 2. Calculate Check Digit
    // GTIN-14 Weights: 3, 1, 3, 1, ...
    let sum = 0;
    for (let i = 0; i < data.length; i++) {
      const digit = parseInt(data[i]);
      const weight = i % 2 === 0 ? 3 : 1;
      sum += digit * weight;
    }

    const nearestTen = Math.ceil(sum / 10) * 10;
    const checkDigit = nearestTen - sum;

    return data + checkDigit;
  },

  generateSSCC: (gln: string): string => {
    // Generate a valid 18-digit SSCC (Serial Shipping Container Code)
    // Structure: Extension (1) + GS1 Company Prefix (7-10) + Serial Ref + Check Digit (1)

    // 1. Extension Digit (0-9). We'll use '1' for "Pallet/Logistics Unit"
    const extension = '1';

    // 2. Company Prefix: Extract first 7 digits from GLN (Assuming standard 7-digit prefix)
    const companyPrefix = gln.substring(0, 7);

    // 3. Serial Reference: Fill remaining space to reach 17 digits total
    // 1 (ext) + 7 (prefix) = 8 digits used. Need 9 more digits for serial reference.
    const serialLength = 17 - extension.length - companyPrefix.length;
    const serialRef = Math.floor(Math.random() * Math.pow(10, serialLength)).toString().padStart(serialLength, '0');

    const data = extension + companyPrefix + serialRef;

    // 4. Calculate Check Digit (Mod 10)
    let sum = 0;
    for (let i = 0; i < data.length; i++) {
      const digit = parseInt(data[i]);
      const distFromRight = data.length - 1 - i;
      const weight = distFromRight % 2 === 0 ? 3 : 1;
      sum += digit * weight;
    }

    const nearestTen = Math.ceil(sum / 10) * 10;
    const checkDigit = nearestTen - sum;

    return data + checkDigit;
  },

  login: async (gln: string, password: string): Promise<User | null> => {
    // Simulate network delay
    await new Promise(resolve => setTimeout(resolve, 600));

    // CLEAN INPUTS: Trim whitespace to prevent copy-paste errors
    const cleanGln = gln.trim();
    const cleanPass = password.trim();

    const users = AuthService.getUsers();

    // Case-sensitive check
    const user = users.find(u => u.gln === cleanGln && u.password === cleanPass);

    if (user) {
      // Return user without password
      const { password: _, ...safeUser } = user;
      return safeUser;
    }
    return null;
  },

  signup: async (name: string, orgName: string, gln: string, role: UserRole, password: string): Promise<User> => {
    await new Promise(resolve => setTimeout(resolve, 800));

    const cleanGln = gln.trim();
    const cleanName = name.trim();
    const cleanOrg = orgName.trim();
    const cleanPass = password.trim();

    // Validate GLN integrity before signup (Warning only for MVP)
    if (!AuthService.validateGS1(cleanGln)) {
       console.warn("GLN Checksum invalid, but proceeding for MVP.");
    }

    const users = AuthService.getUsers();

    if (users.find(u => u.gln === cleanGln)) {
      throw new Error('A user with this GLN already exists.');
    }

    const newUser: UserWithPassword = {
      id: `user-${Date.now()}`,
      name: cleanName,
      orgName: cleanOrg,
      gln: cleanGln,
      role,
      password: cleanPass
    };

    users.push(newUser);
    localStorage.setItem(USERS_STORAGE_KEY, JSON.stringify(users));

    const { password: _, ...safeUser } = newUser;
    return safeUser;
  },

  updateUser: async (updatedData: Partial<User> & { id: string }): Promise<User> => {
    await new Promise(resolve => setTimeout(resolve, 500));

    const users = AuthService.getUsers();
    const index = users.findIndex(u => u.id === updatedData.id);

    if (index === -1) {
      throw new Error('User not found');
    }

    // Update user while preserving password and other fields
    const updatedUserEntry = { ...users[index], ...updatedData };
    users[index] = updatedUserEntry;

    localStorage.setItem(USERS_STORAGE_KEY, JSON.stringify(users));

    const { password: _, ...safeUser } = updatedUserEntry;
    return safeUser;
  },

  resetPassword: async (gln: string, newPassword: string): Promise<boolean> => {
    await new Promise(resolve => setTimeout(resolve, 800));

    const cleanGln = gln.trim();
    const cleanPass = newPassword.trim();

    const users = AuthService.getUsers();
    const index = users.findIndex(u => u.gln === cleanGln);

    if (index === -1) {
      return false; // User not found
    }

    // Update password
    users[index].password = cleanPass;
    localStorage.setItem(USERS_STORAGE_KEY, JSON.stringify(users));
    return true;
  }
};
