```tsx
import React, { useState, useEffect } from 'react';
import { User, Batch, BatchStatus, ReturnReason } from '../types';
import { LedgerService } from '../services/ledgerService';
import { 
  Scan, Truck, AlertTriangle, CheckCircle2, Box, Camera, ArrowDownLeft, RotateCcw, Send, IndianRupee
} from 'lucide-react';
import QRScanner from './QRScanner';
import { toast } from 'react-toastify';
import PrintableInvoice from './PrintableInvoice';

interface DistributorDashboardProps {
  user: User;
}

const DistributorDashboard: React.FC<DistributorDashboardProps> = ({ user }) => {
  const [activeTab, setActiveTab] = useState<'inbound' | 'outbound' | 'returns'>('inbound');
  const [scanInput, setScanInput] = useState('');
  const [scannedBatch, setScannedBatch] = useState<Batch | null>(null);
  const [batches, setBatches] = useState<Batch[]>([]);
  const [loading, setLoading] = useState(false);
  const [actionLoading, setActionLoading] = useState(false);
  const [showScanner, setShowScanner] = useState(false);

  // Outbound / Return specific state
  const [recipientGLN, setRecipientGLN] = useState('');
  const [returnReason, setReturnReason] = useState<ReturnReason>(ReturnReason.DAMAGED);
  const [transactionValue, setTransactionValue] = useState<number>(0);
  const [printData, setPrintData] = useState<any>(null); // To trigger print modal

  const fetchInventory = async () => {
    const data = await LedgerService.getBatches(user);
    setBatches(data);
  };

  useEffect(() => {
    fetchInventory();
  }, [user]);

  const handleScan = async (e?: React.FormEvent, directInput?: string) => {
    if (e) e.preventDefault();
    const query = directInput || scanInput;
    if (!query.trim()) return;

    setLoading(true);
    setScannedBatch(null);

    try {
      let batch = await LedgerService.getBatchByID(query.trim());
      if (!batch) {
        batch = await LedgerService.verifyByHash(query.trim());
      }

      if (batch) {
        setScannedBatch(batch);
        setScanInput(query.trim());
        toast.info(`Found batch: ${batch.productName}`);

        // Auto-set return recipient to manufacturer if returning
        if (activeTab === 'returns') {
            setRecipientGLN(batch.manufacturerGLN);
        }
        setTransactionValue(0); // Reset value input
      } else {
        toast.error('QR Code not recognized on the ledger.');
      }
    } catch (err) {
      toast.error('Scan failed. Please try again.');
    } finally {
      setLoading(false);
    }
  };

  const handleCameraScan = (text: string) => {
    setShowScanner(false);
    setScanInput(text);
    handleScan(undefined, text);
  };

  // Centralized Action Handler
  const executeAction = async () => {
    if (!scannedBatch) return;
    setActionLoading(true);

    try {
      let docType = 'INVOICE';
      let docId = '';

      if (activeTab === 'inbound') {
        // RECEIVE
        await LedgerService.receiveBatch(scannedBatch.batchID, user);
        toast.success(`Received ${scannedBatch.productName} into inventory.`);

      } else if (activeTab === 'outbound') {
        // SEND (Forward Logistics)
        if (!recipientGLN) {
            toast.warning("Please enter a Recipient GLN to send to.");
            setActionLoading(false);
            return;
        }
        // Assuming GST details can be generated or passed. Simplified here.
        const gst = {
            hsnCode: '3004',
            taxableValue: transactionValue,
            taxRate: 12,
            taxAmount: transactionValue * 0.12,
            invoiceNo: `INV-${Date.now()}`,
            invoiceDate: new Date().toISOString()
        };

        await LedgerService.transferBatch(scannedBatch.batchID, recipientGLN, "Retailer/Partner", user, gst);
        toast.success(`Dispatched ${scannedBatch.productName} to ${recipientGLN}`);
        docId = gst.invoiceNo;
        docType = 'INVOICE';

      } else if (activeTab === 'returns') {
        // RETURN (Reverse Logistics)
        if (!recipientGLN) {
            toast.warning("Return destination GLN required.");
            setActionLoading(false);
            return;
        }
        await LedgerService.returnBatch(scannedBatch.batchID, recipientGLN, returnReason, user, transactionValue);
        toast.success(`Returned ${scannedBatch.productName} (Reason: ${returnReason})`);
        docId = `CN-${Date.now()}`;
        docType = 'CREDIT_NOTE';
      }

      // Generate Print Data if Outbound or Return
      if (activeTab !== 'inbound') {
          setPrintData({
              id: docId,
              date: new Date().toISOString(),
              from: { name: user.orgName, gln: user.gln },
              to: { name: 'Partner Entity', gln: recipientGLN },
              items: [{
                  product: scannedBatch.productName,
                  batch: scannedBatch.batchID,
                  hsos: '3004',
                  qty: scannedBatch.quantity,
                  unit: scannedBatch.unit,
                  rate: transactionValue / scannedBatch.quantity,
                  amount: transactionValue
              }],
              total: transactionValue * 1.12, // Simple Tax logic
              tax: { rate: 12, amount: transactionValue * 0.12 }
          });
      }

      setScannedBatch(null);
      setScanInput('');
      setRecipientGLN('');
      fetchInventory(); 
    } catch (err: any) {
      toast.error(err.message || 'Action failed.');
    } finally {
      setActionLoading(false);
    }
  };

  // Metrics
  const inboundCount = batches.filter(b => b.status === BatchStatus.IN_TRANSIT && b.currentOwnerGLN === user.gln).length;
  const inventoryCount = batches.filter(b => b.status === BatchStatus.RECEIVED).length;

  return (
    <div className="space-y-8">
      {/* Print Modal */}
      {printData && (
          <PrintableInvoice 
            type={activeTab === 'returns' ? 'CREDIT_NOTE' : 'INVOICE'} 
            data={printData} 
            onClose={() => setPrintData(null)} 
          />
      )}

      {showScanner && (
        <QRScanner 
          onScan={handleCameraScan} 
          onClose={() => setShowScanner(false)} 
        />
      )}

      {/* Header & Tabs */}
      <div className="flex flex-col md:flex-row justify-between items-start md:items-end gap-4">
        <div>
            <h2 className="text-2xl font-bold text-slate-800">Distributor Operations</h2>
            <p className="text-slate-500">Logistics & Inventory Management</p>
        </div>
        <div className="flex bg-white p-1 rounded-lg border border-slate-200 shadow-sm">
            <button
                onClick={() => { setActiveTab('inbound'); setScannedBatch(null); }}
                className={`px-4 py-2 rounded-md text-sm font-bold flex items-center gap-2 transition-all ${
                    activeTab === 'inbound' ? 'bg-blue-600 text-white shadow' : 'text-slate-500 hover:bg-slate-50'
                }`}
            >
                <ArrowDownLeft size={16} />
                <span>Inbound (Receive)</span>
            </button>
            <button
                onClick={() => { setActiveTab('outbound'); setScannedBatch(null); }}
                className={`px-4 py-2 rounded-md text-sm font-bold flex items-center gap-2 transition-all ${
                    activeTab === 'outbound' ? 'bg-indigo-600 text-white shadow' : 'text-slate-500 hover:bg-slate-50'
                }`}
            >
                <Send size={16} />
                <span>Outbound (Send)</span>
            </button>
            <button
                onClick={() => { setActiveTab('returns'); setScannedBatch(null); }}
                className={`px-4 py-2 rounded-md text-sm font-bold flex items-center gap-2 transition-all ${
                    activeTab === 'returns' ? 'bg-orange-500 text-white shadow' : 'text-slate-500 hover:bg-slate-50'
                }`}
            >
                <RotateCcw size={16} />
                <span>Returns</span>
            </button>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">

        {/* Left Col: The Scanner (Main Workflow) */}
        <div className="lg:col-span-2 space-y-6">

          <div className="bg-white rounded-xl shadow-lg border border-slate-200 overflow-hidden">
            {/* Dynamic Header Color */}
            <div className={`p-6 text-white flex justify-between items-center ${
                activeTab === 'inbound' ? 'bg-blue-600' : 
                activeTab === 'outbound' ? 'bg-indigo-600' : 'bg-orange-500'
            }`}>
              <div>
                <h3 className="text-lg font-bold flex items-center gap-2">
                  <Scan size={24} />
                  <span>
                    {activeTab === 'inbound' ? 'Scan to Receive' : 
                     activeTab === 'outbound' ? 'Scan to Dispatch' : 'Scan for Return'}
                  </span>
                </h3>
                <p className="text-white/80 text-xs mt-1">Scan QR Code on Pallet or Box to initiate action</p>
              </div>
              <button 
                onClick={() => setShowScanner(true)}
                className="bg-white/20 hover:bg-white/30 text-white px-3 py-2 rounded-lg font-bold flex items-center gap-2 transition-colors text-sm"
              >
                <Camera size={18} />
                <span className="hidden sm:inline">Use Camera</span>
              </button>
            </div>

            <div className="p-8">
              <form onSubmit={e => handleScan(e)} className="relative mb-6">
                <input 
                  type="text" 
                  value={scanInput}
                  onChange={e => setScanInput(e.target.value)}
                  placeholder="Focus here to scan..."
                  className="w-full pl-12 pr-4 py-4 text-lg border-2 border-slate-300 rounded-xl focus:border-current focus:ring-0 outline-none transition font-mono shadow-inner"
                  autoFocus
                />
                <Scan className="absolute left-4 top-5 text-slate-400" size={24} />
                <button 
                  type="submit" 
                  className="absolute right-3 top-2.5 bg-slate-800 hover:bg-slate-700 text-white px-4 py-2 rounded-lg font-bold"
                  disabled={loading}
                >
                  {loading ? '...' : 'Lookup'}
                </button>
              </form>

              {scannedBatch && (
                <div className="mt-6 border border-slate-200 rounded-xl overflow-hidden animate-in slide-in-from-bottom-4">
                  <div className="bg-slate-50 p-4 border-b border-slate-200 flex justify-between items-center">
                    <h4 className="font-bold text-slate-800">Item Details</h4>
                    <span className={`px-2 py-1 rounded text-xs font-bold uppercase ${
                      scannedBatch.status === 'IN_TRANSIT' ? 'bg-blue-100 text-blue-700' : 'bg-gray-100 text-gray-600'
                    }`}>
                      {scannedBatch.status.replace('_', ' ')}
                    </span>
                  </div>
                  <div className="p-6 grid grid-cols-2 gap-4">
                     <div>
                       <p className="text-xs text-slate-400 uppercase font-bold">Product</p>
                       <p className="font-medium text-lg text-slate-900">{scannedBatch.productName}</p>
                     </div>
                     <div>
                       <p className="text-xs text-slate-400 uppercase font-bold">Batch ID</p>
                       <p className="font-mono text-slate-600 text-sm">{scannedBatch.batchID}</p>
                     </div>
                     <div>
                       <p className="text-xs text-slate-400 uppercase font-bold">Quantity</p>
                       <p className="font-medium text-slate-900">{scannedBatch.quantity} {scannedBatch.unit}</p>
                     </div>
                     <div>
                       <p className="text-xs text-slate-400 uppercase font-bold">Expiry</p>
                       <p className="font-medium text-slate-900">{scannedBatch.expiryDate}</p>
                     </div>
                  </div>

                  {/* Context Specific Forms */}
                  {(activeTab === 'outbound' || activeTab === 'returns') && (
                      <div className="p-6 bg-slate-50 border-t border-slate-200 space-y-4">
                          <div>
                              <label className="block text-xs font-bold text-slate-500 uppercase mb-1">
                                  {activeTab === 'returns' ? 'Return To (Manufacturer GLN)' : 'Send To (Retailer GLN)'}
                              </label>
                              <input 
                                value={recipientGLN}
