## components/TraceVisualizer.tsx

Visualized money transaction flow in the trace.

```tsx
import React, { useEffect, useState } from 'react';
import { useParams, Link } from 'react-router-dom';
import { Batch, User } from '../types';
import { LedgerService } from '../services/ledgerService';
import { 
  CheckCircle2, 
  MapPin, 
  User as UserIcon, 
  Clock, 
  ArrowLeft,
  FileBadge,
  FileText,
  Truck,
  IndianRupee
} from 'lucide-react';

const TraceVisualizer = ({ user }: { user: User }) => {
  const { id } = useParams<{ id: string }>();
  const [batch, setBatch] = useState<Batch | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const fetchBatch = async () => {
      if (!id) return;
      const data = await LedgerService.getBatchByID(id);
      if (data) setBatch(data);
      setLoading(false);
    };
    fetchBatch();
  }, [id]);

  if (loading) return <div className="p-8 text-center">Tracing Batch...</div>;
  if (!batch) return <div className="p-8 text-center text-red-500">Batch not found on ledger.</div>;

  return (
    <div className="max-w-4xl mx-auto">
      <Link to="/batches" className="flex items-center space-x-2 text-slate-500 hover:text-slate-800 mb-6 transition-colors">
        <ArrowLeft size={18} />
        <span>Back to Inventory</span>
      </Link>

      <div className="bg-white rounded-xl shadow-lg border border-slate-100 overflow-hidden mb-8">
        <div className="p-6 bg-slate-50 border-b border-slate-200 flex justify-between items-start">
          <div>
            <h1 className="text-2xl font-bold text-slate-900 mb-1">{batch.productName}</h1>
            <div className="flex items-center space-x-4 text-sm text-slate-500 font-mono">
              <span>ID: {batch.batchID}</span>
              <span>•</span>
              <span>GTIN: {batch.gtin}</span>
            </div>
          </div>
          <div className="text-right">
             <span className="bg-blue-100 text-blue-700 px-3 py-1 rounded-full text-sm font-bold tracking-wide uppercase">
               {batch.status.replace('_', ' ')}
             </span>
             <p className="text-xs text-slate-400 mt-2">Owner GLN: {batch.currentOwnerGLN}</p>
          </div>
        </div>

        <div className="p-6 grid grid-cols-3 gap-6">
          <div className="p-4 bg-slate-50 rounded-lg">
             <p className="text-xs text-slate-400 uppercase font-bold tracking-wider mb-1">Manufacturer</p>
             <p className="font-mono text-sm">{batch.manufacturerGLN}</p>
          </div>
          <div className="p-4 bg-slate-50 rounded-lg">
             <p className="text-xs text-slate-400 uppercase font-bold tracking-wider mb-1">Expiry</p>
             <p className="font-mono text-sm">{batch.expiryDate}</p>
          </div>
          <div className="p-4 bg-slate-50 rounded-lg">
             <p className="text-xs text-slate-400 uppercase font-bold tracking-wider mb-1">Qty / Unit</p>
             <p className="font-mono text-sm">{batch.quantity} {batch.unit}</p>
          </div>
        </div>
      </div>

      {/* Timeline */}
      <div className="relative pl-8 border-l-2 border-slate-200 space-y-12 pb-12">
        {batch.trace.sort((a,b) => new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime()).map((event, index) => (
          <div key={event.eventID} className="relative">
            {/* Dot */}
            <div className={`absolute -left-[41px] p-1 bg-white border-4 ${index === 0 ? 'border-blue-500' : 'border-slate-300'} rounded-full`}>
               <CheckCircle2 size={20} className={index === 0 ? 'text-blue-500' : 'text-slate-400'} />
            </div>

            <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200 hover:shadow-md transition-shadow">
              <div className="flex justify-between items-start mb-4">
                <div>
                  <h3 className="text-lg font-bold text-slate-800 flex items-center gap-2">
                    {event.type}
                    {event.type === 'MANUFACTURE' && <FileBadge size={18} className="text-amber-500"/>}
                    {event.type === 'DISPATCH' && <Truck size={18} className="text-blue-500"/>}
                  </h3>
                  <div className="flex items-center space-x-4 text-sm text-slate-500 mt-1">
                    <span className="flex items-center space-x-1">
                      <Clock size={14} />
                      <span>{new Date(event.timestamp).toLocaleString()}</span>
                    </span>
                  </div>
                </div>
                <div className="bg-slate-50 px-3 py-1 rounded text-xs font-mono text-slate-400 border border-slate-200">
                  Tx: {event.txHash.substring(0, 12)}...
                </div>
              </div>

              <div className="grid grid-cols-2 gap-4 text-sm text-slate-600">
                <div className="flex items-center space-x-2">
                  <UserIcon size={16} className="text-slate-400" />
                  <span className="font-medium">{event.actorName}</span>
                </div>
                <div className="flex items-center space-x-2">
                   <MapPin size={16} className="text-slate-400" />
                   <span>{event.location}</span>
                </div>
              </div>

              {/* Render Money Trail */}
              {event.metadata && (event.metadata.gst || event.metadata.amount || event.metadata.refundAmount) && (
                  <div className="mt-4 pt-4 border-t border-slate-100">
                      <div className="bg-green-50 border border-green-200 rounded-lg p-3 flex items-center gap-3">
                          <div className="bg-green-100 p-2 rounded-full text-green-700">
                              <IndianRupee size={18} />
                          </div>
                          <div>
                              <p className="text-xs font-bold text-green-800 uppercase">Transaction Value</p>
                              <div className="flex items-baseline gap-2">
                                  <span className="font-bold text-lg text-slate-900">
                                      ₹{Number(event.metadata.gst?.taxableValue || event.metadata.amount || event.metadata.refundAmount).toLocaleString()}
                                  </span>
                                  {event.metadata.refundAmount && <span className="text-xs text-red-500 font-bold">(REFUND)</span>}
                              </div>
                          </div>
                          {event.metadata.gst && (
                              <div className="ml-auto text-right text-xs text-slate-500">
                                  <p>Invoice: {event.metadata.gst.invoiceNo}</p>
                                  <p>Tax: {event.metadata.gst.taxRate}%</p>
                              </div>
                          )}
                      </div>
                  </div>
              )}

              {/* Render E-Way Bill */}
              {event.metadata && event.metadata.ewayBill && (
                <div className="mt-4 pt-4 border-t border-slate-100">
                     <div className="bg-emerald-50 rounded-lg p-3 border border-emerald-100 flex items-start gap-3">
                        <FileText className="text-emerald-600 mt-1" size={20} />
                        <div>
                           <p className="text-xs font-bold text-emerald-800 uppercase">E-Way Bill Generated</p>
                           <p className="text-sm font-mono font-bold text-emerald-900">{event.metadata.ewayBill.ewbNo}</p>
                           <p className="text-[10px] text-emerald-600 mt-1">
                             Valid Until: {new Date(event.metadata.ewayBill.validUntil).toLocaleDateString()}
                           </p>
                        </div>
                     </div>
                </div>
              )}

              {/* Other Metadata */}
              {event.metadata && (
                <div className="mt-4 pt-4 border-t border-slate-100">
                   <p className="text-xs font-bold text-slate-400 uppercase mb-2">Technical Metadata</p>
                   <div className="grid grid-cols-2 gap-2">
                    {Object.entries(event.metadata)
                      .filter(([key]) => !['ewayBill', 'gst', 'amount', 'refundAmount', 'paymentStatus', 'paymentMethod'].includes(key))
                      .map(([key, val]) => (
                      <div key={key} className="bg-slate-50 px-3 py-2 rounded text-xs break-all">
                        <span className="font-semibold text-slate-500 mr-2">{key}:</span>
                        <span className="font-mono">{typeof val === 'object' ? JSON.stringify(val) : val}</span>
                      </div>
                    ))}
                   </div>
                </div>
              )}
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};

export default TraceVisualizer;

