import React, { useState, useEffect } from 'react';
import { HashRouter as Router, Routes, Route, Navigate } from 'react-router-dom';
import Layout from './components/Layout';
import Dashboard from './components/Dashboard';
import BatchManager from './components/BatchManager';
import TraceVisualizer from './components/TraceVisualizer';
import Assistant from './components/Assistant';
import Login from './components/Login';
import Signup from './components/Signup';
import UserProfile from './components/UserProfile';
import ProductVerifier from './components/ProductVerifier';
import SSCCManager from './components/SSCCManager';
import VRSManager from './components/VRSManager';
import NetworkDirectory from './components/NetworkDirectory';
import FinancialRecords from './components/FinancialRecords'; // New Import
import { User } from './types';
import { ToastContainer } from 'react-toastify';

const SESSION_KEY = 'eledger_active_session';

const App: React.FC = () => {
  // Initialize user state by checking localStorage for an active session
  const [currentUser, setCurrentUser] = useState<User | null>(() => {
    try {
      const storedSession = localStorage.getItem(SESSION_KEY);
      return storedSession ? JSON.parse(storedSession) : null;
    } catch (error) {
      console.error("Failed to parse session:", error);
      localStorage.removeItem(SESSION_KEY); // Clean up invalid session
      return null;
    }
  });

  // Sync session across tabs
  useEffect(() => {
    const handleStorageChange = (event: StorageEvent) => {
      if (event.key === SESSION_KEY) {
        if (event.newValue) {
          try {
            const user = JSON.parse(event.newValue);
            setCurrentUser(user);
          } catch (e) {
            console.error("Error parsing session from storage event", e);
          }
        } else {
          // Key removed (logout)
          setCurrentUser(null);
        }
      }
    };

    window.addEventListener('storage', handleStorageChange);
    return () => window.removeEventListener('storage', handleStorageChange);
  }, []);

  // Handle Login: Save user to state and localStorage
  const handleLogin = (user: User) => {
    localStorage.setItem(SESSION_KEY, JSON.stringify(user));
    setCurrentUser(user);
  };

  // Handle Logout: Clear state and localStorage
  const handleLogout = () => {
    localStorage.removeItem(SESSION_KEY);
    setCurrentUser(null);
  };

  // Handle User Update: Update state and active session
  const handleUserUpdate = (updatedUser: User) => {
    setCurrentUser(updatedUser);
    localStorage.setItem(SESSION_KEY, JSON.stringify(updatedUser));
  };

  return (
    <Router>
      <ToastContainer 
        position="top-right" 
        autoClose={4000} 
        hideProgressBar={false} 
        newestOnTop={true} 
        closeOnClick 
        rtl={false} 
        pauseOnFocusLoss 
        draggable 
        pauseOnHover 
        theme="colored" 
      />
      <Routes>
        {/* Public Auth Routes */}
        <Route 
          path="/login" 
          element={
            currentUser ? (
              <Navigate to="/dashboard" replace />
            ) : (
              <Login onLogin={handleLogin} />
            )
          } 
        />
        <Route 
          path="/signup" 
          element={
            currentUser ? (
              <Navigate to="/dashboard" replace />
            ) : (
              <Signup />
            )
          } 
        />

        {/* Protected Application Routes */}
        <Route
          path="/*"
          element={
            currentUser ? (
              <Layout user={currentUser} onLogout={handleLogout}>
                <Routes>
                  <Route path="/" element={<Navigate to="/dashboard" replace />} />
                  <Route path="/dashboard" element={<Dashboard user={currentUser} />} />
                  <Route path="/batches" element={<BatchManager user={currentUser} />} />
                  <Route path="/trace/:id" element={<TraceVisualizer user={currentUser} />} />
                  <Route path="/assistant" element={<Assistant />} />
                  <Route path="/transfers" element={<BatchManager user={currentUser} />} />
                  <Route path="/reports" element={<Dashboard user={currentUser} />} />
                  <Route path="/profile" element={<UserProfile user={currentUser} onUpdate={handleUserUpdate} />} />
                  <Route path="/verify" element={<ProductVerifier />} />
                  <Route path="/sscc" element={<SSCCManager user={currentUser} />} />
                  <Route path="/vrs" element={<VRSManager user={currentUser} />} />
                  <Route path="/network" element={<NetworkDirectory />} />
                  <Route path="/financials" element={<FinancialRecords user={currentUser} />} /> 
                  {/* Fallback for unknown protected routes */}
                  <Route path="*" element={<Navigate to="/dashboard" replace />} />
                </Routes>
              </Layout>
            ) : (
              <Navigate to="/login" replace />
            )
          }
        />
      </Routes>
    </Router>
  );
};

export default App;

