import React, { useState, useEffect } from 'react';
import { User, Batch, BatchStatus, ReturnReason } from '../types';
import { LedgerService } from '../services/ledgerService';
import { 
  Scan, ShoppingBag, ArrowDownToLine, CreditCard, 
