} from 'lucide-react';
import QRScanner from './QRScanner';
import { toast } from 'react-toastify';
import PrintableInvoice from './PrintableInvoice';

interface RetailerDashboardProps {
  user: User;
}

const RetailerDashboard: React.FC<RetailerDashboardProps> = ({ user }) => {
  const [activeMode, setActiveMode] = useState<'receive' | 'dispense' | 'return'>('dispense');

  const [scanInput, setScanInput] = useState('');
  const [scannedBatch, setScannedBatch] = useState<Batch | null>(null);
  const [loading, setLoading] = useState(false);
  const [actionLoading, setActionLoading] = useState(false);
  const [showScanner, setShowScanner] = useState(false);
  const [inventory, setInventory] = useState<Batch[]>([]);

  // Action fields
  const [returnGLN, setReturnGLN] = useState('');
  const [returnReason, setReturnReason] = useState<ReturnReason>(ReturnReason.DAMAGED);
  const [salePrice, setSalePrice] = useState<number>(0);
  const [refundPrice, setRefundPrice] = useState<number>(0);

  const [printData, setPrintData] = useState<any>(null); // For receipt printing

  useEffect(() => {
    fetchInventory();
  }, [user]);

  const fetchInventory = async () => {
    const data = await LedgerService.getBatches(user);
    setInventory(data);
  };

  const handleScan = async (e?: React.FormEvent, directInput?: string) => {
    if (e) e.preventDefault();
    const query = directInput || scanInput;
    if (!query.trim()) return;

    setLoading(true);
    setScannedBatch(null);

    try {
      let batch = await LedgerService.getBatchByID(query.trim());
      if (!batch) {
        batch = await LedgerService.verifyByHash(query.trim());
      }

      if (batch) {
        setScannedBatch(batch);
        setScanInput(query.trim());
        toast.info(`Item found: ${batch.productName}`);

        // Auto-fill
        if (activeMode === 'return') {
            setReturnGLN(batch.manufacturerGLN); 
            setRefundPrice(0);
        } else {
            setSalePrice(0);
        }
      } else {
        toast.error('Product not found on ledger.');
      }
    } catch (err) {
      toast.error('Scan failed.');
    } finally {
      setLoading(false);
    }
  };

  const handleCameraScan = (text: string) => {
    setShowScanner(false);
    setScanInput(text);
    handleScan(undefined, text);
  };

  const executeAction = async () => {
    if (!scannedBatch) return;
    setActionLoading(true);
    try {
      if (activeMode === 'receive') {
        await LedgerService.receiveBatch(scannedBatch.batchID, user);
        toast.success(`Stock received: ${scannedBatch.productName}`);

      } else if (activeMode === 'dispense') {
        // Prepare Payment Details
        const payment = {
            status: 'PAID' as any,
            method: 'CASH' as any,
            amount: salePrice,
            currency: 'INR',
            timestamp: new Date().toISOString()
        };
        await LedgerService.sellBatch(scannedBatch.batchID, user, payment);
        toast.success(`Sale recorded: ${scannedBatch.productName}`);

        // Generate Receipt
        setPrintData({
            id: `RCPT-${Date.now()}`,
            date: new Date().toISOString(),
            from: { name: user.orgName, gln: user.gln, address: 'Retail Store Output' },
            to: { name: 'Consumer (Walk-in)', gln: 'N/A', address: '' },
            items: [{
                product: scannedBatch.productName,
                batch: scannedBatch.batchID,
                hsos: 'N/A',
                qty: scannedBatch.quantity,
                unit: scannedBatch.unit,
                rate: salePrice / scannedBatch.quantity || 0,
                amount: salePrice
            }],
            total: salePrice,
            tax: { rate: 0, amount: 0 } // Retail usually inclusive
        });

      } else if (activeMode === 'return') {
        if (!returnGLN) {
            toast.warning("Destination GLN required for return.");
            setActionLoading(false);
            return;
        }
        await LedgerService.returnBatch(scannedBatch.batchID, returnGLN, returnReason, user, refundPrice);
        toast.success(`Returned ${scannedBatch.productName} to ${returnGLN}`);
      }

      setScannedBatch(null);
      setScanInput('');
      setReturnGLN('');
      fetchInventory();
    } catch (err: any) {
      toast.error(err.message || 'Action failed.');
    } finally {
