                  <h3 className={`text-lg font-bold flex items-center gap-2 ${isReturn ? 'text-orange-700' : 'text-slate-800'}`}>
                    {event.type}
                    {event.type === 'MANUFACTURE' && <FileBadge size={18} className="text-amber-500"/>}
                    {isDispatch && <Truck size={18} className="text-blue-500"/>}
                    {isReturn && <AlertOctagon size={18} className="text-orange-500" />}
                  </h3>
                  <div className="flex items-center space-x-4 text-sm text-slate-500 mt-1">
                    <span className="flex items-center space-x-1">
                      <Clock size={14} />
                      <span>{new Date(event.timestamp).toLocaleString()}</span>
                    </span>
                  </div>
                </div>
                <div className="bg-slate-50 px-3 py-1 rounded text-xs font-mono text-slate-400 border border-slate-200">
