  status: VerificationStatus;
  responseMessage?: string;
}

export enum PaymentStatus {
  PAID = 'PAID',
  CREDIT = 'CREDIT',
  PENDING = 'PENDING'
}

export interface PaymentDetails {
  status: PaymentStatus;
  method: 'CASH' | 'CARD' | 'INSURANCE' | 'INVOICE';
