);

const ManufacturerDashboard: React.FC<ManufacturerDashboardProps> = ({ user }) => {
  const [batches, setBatches] = useState<Batch[]>([]);
  const [loading, setLoading] = useState(true);

  // Scanning State for Returns
  const [showScanner, setShowScanner] = useState(false);
  const [scanInput, setScanInput] = useState('');
  const [scannedBatch, setScannedBatch] = useState<Batch | null>(null);
  const [actionLoading, setActionLoading] = useState(false);

  useEffect(() => {
    fetchData();
  }, [user]);

  const fetchData = async () => {
    const data = await LedgerService.getBatches(user);
    setBatches(data);
    setLoading(false);
  };

  // --- STANDARD METRICS ---
  const totalBatches = batches.length;
  const inTransit = batches.filter(b => b.status === BatchStatus.IN_TRANSIT).length;
  const expiries = batches.filter(b => new Date(b.expiryDate) < new Date(new Date().setFullYear(new Date().getFullYear() + 1))).length;
  const received = batches.filter(b => b.status === BatchStatus.RECEIVED || b.status === BatchStatus.SOLD).length;
  const quarantined = batches.filter(b => b.status === BatchStatus.QUARANTINED).length;

  const validGTINs = batches.filter(b => AuthService.validateGS1(b.gtin)).length;
  const gtinComplianceRate = totalBatches > 0 ? Math.round((validGTINs / totalBatches) * 100) : 100;

  const statusData = [
    { name: 'Created', value: batches.filter(b => b.status === 'CREATED').length },
    { name: 'In Transit', value: batches.filter(b => b.status === 'IN_TRANSIT').length },
    { name: 'Received', value: batches.filter(b => b.status === 'RECEIVED').length },
    { name: 'Sold', value: batches.filter(b => b.status === 'SOLD').length },
    { name: 'Returned/Quarantined', value: quarantined }
  ].filter(d => d.value > 0);

  const COLORS = ['#94a3b8', '#3b82f6', '#10b981', '#6366f1', '#f97316'];

  // --- SCANNING LOGIC ---
  const handleScan = async (e?: React.FormEvent, directInput?: string) => {
    if (e) e.preventDefault();
    const query = directInput || scanInput;
    if (!query.trim()) return;

    setScannedBatch(null);

    try {
      let batch = await LedgerService.getBatchByID(query.trim());
      if (!batch) {
        batch = await LedgerService.verifyByHash(query.trim());
      }

      if (batch) {
        if (batch.intendedRecipientGLN !== user.gln) {
            toast.warning(`This batch is not currently inbound to your GLN. Current owner: ${batch.currentOwnerGLN}`);
        } else {
            setScannedBatch(batch);
            setScanInput(query.trim());
            toast.info(`Found batch: ${batch.productName}`);
        }
      } else {
        toast.error('QR Code not recognized on the ledger.');
      }
    } catch (err) {
      toast.error('Scan failed. Please try again.');
    } 
  };

  const handleCameraScan = (text: string) => {
    setShowScanner(false);
    setScanInput(text);
    handleScan(undefined, text);
  };

  const executeReceive = async () => {
    if (!scannedBatch) return;
    setActionLoading(true);
    try {
        await LedgerService.receiveBatch(scannedBatch.batchID, user);
        toast.success(`Confirmed receipt of ${scannedBatch.productName}.`);
        setScannedBatch(null);
        setScanInput('');
        fetchData();
    } catch (err: any) {
        toast.error(err.message || 'Receive failed.');
    } finally {
        setActionLoading(false);
    }
  };

  if (loading) return <div className="animate-pulse flex space-x-4 p-8"><div className="h-12 w-full bg-slate-200 rounded"></div></div>;

  return (
    <div className="space-y-8 pb-12">
