        <StatCard title="Active Shipments" value={inTransit} icon={Truck} color="bg-indigo-500" />
        <StatCard title="Risk / Near Expiry" value={expiries} icon={AlertTriangle} color="bg-orange-500" />
        <StatCard title="Returns/Quarantined" value={quarantined} icon={RotateCcw} color="bg-red-500" />
      </div>

      {/* Operations Area */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">

          {/* Scan Module */}
          <div className="lg:col-span-2">
             <div className="bg-white rounded-xl shadow-lg border border-slate-200 overflow-hidden">
                <div className="bg-slate-800 p-6 text-white flex justify-between items-center">
                    <div>
                        <h3 className="text-lg font-bold flex items-center gap-2">
                            <ScanBarcode size={24} className="text-orange-400" />
                            <span>Scan Returns & Inbound</span>
                        </h3>
                        <p className="text-xs text-slate-300 mt-1">Receive returned goods or transferred stock back into your warehouse.</p>
                    </div>
                    <button 
                        onClick={() => setShowScanner(true)}
                        className="bg-white/20 hover:bg-white/30 text-white px-3 py-2 rounded-lg font-bold flex items-center gap-2 text-sm transition-colors"
                    >
                        <Camera size={18} />
                        <span className="hidden sm:inline">Use Camera</span>
                    </button>
                </div>

                <div className="p-8">
                    <form onSubmit={e => handleScan(e)} className="relative mb-6">
                        <input 
                        type="text" 
                        value={scanInput}
                        onChange={e => setScanInput(e.target.value)}
                        placeholder="Scan Batch ID or Integrity Hash..."
                        className="w-full pl-12 pr-4 py-4 text-lg border-2 border-slate-300 rounded-xl focus:border-orange-500 focus:ring-0 outline-none transition font-mono shadow-inner"
                        autoFocus
                        />
                        <ScanBarcode className="absolute left-4 top-5 text-slate-400" size={24} />
                        <button type="submit" className="absolute right-3 top-2.5 bg-slate-800 hover:bg-slate-700 text-white px-4 py-2 rounded-lg font-bold">
                        Lookup
                        </button>
                    </form>

                    {scannedBatch && (
                        <div className="mt-6 border border-slate-200 rounded-xl overflow-hidden animate-in slide-in-from-bottom-4">
                            <div className="bg-orange-50 p-4 border-b border-orange-200 flex justify-between items-center">
                                <h4 className="font-bold text-orange-900">Confirm Receipt</h4>
                                <span className="bg-white border border-orange-200 text-orange-700 px-2 py-1 rounded text-xs font-bold uppercase">
                                    {scannedBatch.status.replace('_', ' ')}
                                </span>
                            </div>
                            <div className="p-6">
                                <div className="flex justify-between items-start mb-4">
                                    <div>
                                        <p className="text-lg font-bold text-slate-800">{scannedBatch.productName}</p>
                                        <p className="font-mono text-sm text-slate-500">{scannedBatch.batchID}</p>
