import React, { useEffect, useState } from 'react';
import { Batch, User, UserRole, BatchStatus } from '../types';
import { LedgerService } from '../services/ledgerService';
import { 
  PackageCheck, AlertTriangle, Truck, Activity
} from 'lucide-react';
import DistributorDashboard from './DistributorDashboard';
import RetailerDashboard from './RetailerDashboard';
import ManufacturerDashboard from './ManufacturerDashboard';

interface DashboardProps {
  user: User;
}

const StatCard = ({ title, value, icon: Icon, color, subtitle }: { title: string; value: string | number; icon: any; color: string; subtitle?: string }) => (
  <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-100 flex items-start justify-between transition-all hover:shadow-md">
    <div>
      <p className="text-sm font-medium text-slate-500 mb-1">{title}</p>
      <h3 className="text-2xl font-bold text-slate-800">{value}</h3>
      {subtitle && <p className="text-xs text-slate-400 mt-1">{subtitle}</p>}
    </div>
    <div className={`p-3 rounded-lg ${color} bg-opacity-10`}>
      <Icon className={color.replace('bg-', 'text-')} size={24} />
    </div>
  </div>
);

const Dashboard: React.FC<DashboardProps> = ({ user }) => {
  // --- ROLE ROUTING ---
  if (user.role === UserRole.DISTRIBUTOR) {
    return <DistributorDashboard user={user} />;
  }

  if (user.role === UserRole.RETAILER) {
    return <RetailerDashboard user={user} />;
  }

  if (user.role === UserRole.MANUFACTURER) {
    return <ManufacturerDashboard user={user} />;
  }

  // --- REGULATOR / AUDITOR DEFAULT VIEW ---
  // (Simplified stats view for Regulators for now)

  // eslint-disable-next-line react-hooks/rules-of-hooks
  const [batches, setBatches] = useState<Batch[]>([]);
  // eslint-disable-next-line react-hooks/rules-of-hooks
  const [loading, setLoading] = useState(true);

  // eslint-disable-next-line react-hooks/rules-of-hooks
  useEffect(() => {
    const fetchData = async () => {
      const data = await LedgerService.getBatches(user);
      setBatches(data);
      setLoading(false);
    };
    fetchData();
  }, [user]);

  if (loading) return <div className="p-8">Loading Regulator Dashboard...</div>;

  const totalBatches = batches.length;
  const inTransit = batches.filter(b => b.status === BatchStatus.IN_TRANSIT).length;
  const expiries = batches.filter(b => new Date(b.expiryDate) < new Date(new Date().setFullYear(new Date().getFullYear() + 1))).length;
  const completed = batches.filter(b => b.status === BatchStatus.SOLD || b.status === BatchStatus.DESTROYED).length;

  return (
    <div className="space-y-8">
      <h2 className="text-2xl font-bold text-slate-800">Regulator Oversight Dashboard</h2>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        <StatCard title="Total Batches" value={totalBatches} icon={PackageCheck} color="bg-blue-500" />
        <StatCard title="In Motion" value={inTransit} icon={Truck} color="bg-indigo-500" />
        <StatCard title="Alerts" value={expiries} icon={AlertTriangle} color="bg-orange-500" />
        <StatCard title="Completed" value={completed} icon={Activity} color="bg-emerald-500" />
      </div>

      <div className="bg-white p-8 rounded-xl shadow-sm border border-slate-200 text-center text-slate-500">
        <p>Full regulator reporting suite active. See "Compliance Reports" for detailed analysis.</p>
      </div>
    </div>
  );
};

