import React, { useState } from 'react';
import { Batch, User, GSTDetails, EWayBill } from '../types';
import { Truck, FileText, IndianRupee, ShieldCheck, Printer, ArrowRight } from 'lucide-react';
import { toast } from 'react-toastify';
import PrintableInvoice from './PrintableInvoice';

interface TransferModalProps {
  batch: Batch; 
  onClose: () => void;
  onSubmit: (toGLN: string, toName: string, gst?: GSTDetails, ewbPartial?: Partial<EWayBill>) => Promise<void>;
  currentUser: User;
}

const TransferModal: React.FC<TransferModalProps> = ({ batch, onClose, onSubmit, currentUser }) => {
  const [step, setStep] = useState<1 | 2>(1); // 1: Recipient, 2: Compliance
  const [loading, setLoading] = useState(false);
  const [printData, setPrintData] = useState<any>(null); // For print view after success

  // Basic Info
  const [recipient, setRecipient] = useState({ gln: '', name: '' });

  // Compliance Info
  const [gstData, setGstData] = useState({
    hsn: '3004',
    value: 10000 * (batch.quantity || 1), 
    rate: 12,
    invoiceNo: `INV-${Date.now().toString().slice(-6)}`,
  });

  const [transportData, setTransportData] = useState({
    vehicleNo: '',
    distance: 100,
    fromPlace: 'Warehouse A',
    toPlace: ''
  });

  const taxAmount = (gstData.value * gstData.rate) / 100;
  const totalAmount = gstData.value + taxAmount;

  const handleSubmit = async () => {
    if (!recipient.gln || !recipient.name) {
      toast.error("Recipient details required");
      return;
    }

    setLoading(true);

    const gst: GSTDetails = {
      hsnCode: gstData.hsn,
      taxableValue: gstData.value,
      taxRate: gstData.rate,
      taxAmount: taxAmount,
      invoiceNo: gstData.invoiceNo,
      invoiceDate: new Date().toISOString()
    };

    const ewbPartial: Partial<EWayBill> = {
      vehicleNo: transportData.vehicleNo,
      distanceKm: transportData.distance,
      fromPlace: transportData.fromPlace,
      toPlace: transportData.toPlace || recipient.name + ' Depot'
    };

    try {
      await onSubmit(recipient.gln, recipient.name, gst, ewbPartial);

      // Prepare print data on success
      setPrintData({
        id: gstData.invoiceNo,
        date: new Date().toISOString(),
        from: { name: currentUser.orgName, gln: currentUser.gln },
        to: recipient,
        items: [{
            product: batch.productName,
            batch: batch.batchID,
            hsos: gstData.hsn,
            qty: batch.quantity,
            unit: batch.unit,
            rate: gstData.value / (batch.quantity || 1),
            amount: gstData.value
        }],
        tax: { rate: gstData.rate, amount: taxAmount },
        total: totalAmount,
        ewayBill: {
            ewbNo: '141' + Math.floor(100000000 + Math.random() * 900000000), // Simulated generation
            vehicleNo: transportData.vehicleNo,
            fromPlace: transportData.fromPlace,
            toPlace: transportData.toPlace || recipient.name + ' Depot',
            distanceKm: transportData.distance,
            validUntil: new Date(Date.now() + 86400000).toISOString(), // +1 day
            generatedDate: new Date().toISOString()
        }
      });
    } catch (error) {
      console.error(error);
      // Toast handled by parent or service usually, but ensuring loading stops
    } finally {
      setLoading(false);
    }
  };

  if (printData) {
    return <PrintableInvoice type="INVOICE" data={printData} onClose={onClose} />;
  }

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 backdrop-blur-sm p-4">
      <div className="bg-white rounded-2xl shadow-xl w-full max-w-lg overflow-hidden flex flex-col max-h-[90vh]">
        {/* Header */}
        <div className="bg-slate-900 p-4 text-white flex justify-between items-center">
          <h3 className="text-lg font-bold flex items-center gap-2">
            <Truck className="text-blue-400" />
            <span>Initiate Transfer</span>
          </h3>
          <button onClick={onClose} className="text-slate-400 hover:text-white">✕</button>
        </div>

        <div className="flex-1 overflow-y-auto p-6">
          <div className="mb-6 flex items-center justify-between text-sm">
             <div className={`flex items-center gap-2 ${step === 1 ? 'text-blue-600 font-bold' : 'text-slate-400'}`}>
                <span className="w-6 h-6 rounded-full bg-slate-100 flex items-center justify-center border border-slate-200">1</span>
                <span>Recipient</span>
             </div>
             <div className="h-px bg-slate-200 flex-1 mx-4"></div>
             <div className={`flex items-center gap-2 ${step === 2 ? 'text-blue-600 font-bold' : 'text-slate-400'}`}>
                <span className="w-6 h-6 rounded-full bg-slate-100 flex items-center justify-center border border-slate-200">2</span>
                <span>E-Way Bill & Tax</span>
             </div>
          </div>

          <div className="bg-slate-50 p-4 rounded-lg mb-6 border border-slate-200 text-sm">
             <p className="text-slate-500">Product:</p>
             <p className="font-bold text-slate-800">{batch.productName} <span className="font-normal text-slate-500">({batch.quantity} {batch.unit})</span></p>
          </div>

          {step === 1 && (
