import { User, UserRole } from '../types';
import { MOCK_USERS } from '../constants';

// Extending User interface locally to include password for simulation
interface UserWithPassword extends User {
  password?: string;
}

const USERS_STORAGE_KEY = 'eledger_users';

export const AuthService = {
  // Initialize with mock users if empty, with robustness against corruption
  getUsers: (): UserWithPassword[] => {
    try {
      const stored = localStorage.getItem(USERS_STORAGE_KEY);
      if (!stored) {
        // Seed with mock users, default password is 'password'
        const initialUsers: UserWithPassword[] = MOCK_USERS.map(u => ({ ...u, password: 'password' }));
        localStorage.setItem(USERS_STORAGE_KEY, JSON.stringify(initialUsers));
        return initialUsers;
      }

      const parsedUsers = JSON.parse(stored);

      // SELF-HEALING: Patch missing passwords if legacy data exists
      if (parsedUsers.some((u: any) => !u.password)) {
        const fixedUsers = parsedUsers.map((u: any) => ({
          ...u,
          password: u.password || 'password'
        }));
        localStorage.setItem(USERS_STORAGE_KEY, JSON.stringify(fixedUsers));
        return fixedUsers;
      }

      return parsedUsers;
    } catch (e) {
      console.error("Auth DB Error", e);
      // Fallback to mocks if storage is corrupt
      return MOCK_USERS.map(u => ({ ...u, password: 'password' }));
    }
  },

  /**
   * Check if a user exists by GLN (Async simulation)
   */
