                    <Loader2 size={20} className="animate-spin" />
                    <span>Authenticating...</span>
                  </>
                ) : (
                  <>
                    <span>Sign In</span>
                    <ArrowRight size={18} />
                  </>
                )}
              </button>
            </form>
          ) : (
            <form onSubmit={handleResetSubmit} className="space-y-5">
              {resetStep === 1 && (
                <>
                  <p className="text-sm text-slate-600 text-center mb-4">
                    Enter your GLN to locate your account.
                  </p>
                  <div>
                    <label className="block text-xs font-semibold text-slate-500 uppercase tracking-wider mb-1.5">
                      Your GLN
                    </label>
                    <input
                      type="text"
                      required
                      value={resetGln}
                      onChange={(e) => setResetGln(e.target.value)}
                      className="w-full border border-slate-300 rounded-lg px-4 py-3 focus:ring-2 focus:ring-blue-500 font-mono text-sm"
                      placeholder="0000000000000"
                    />
                  </div>
                  <button
                    type="button"
                    disabled={loading}
                    onClick={handleVerifyUser}
                    className="w-full bg-slate-800 hover:bg-slate-700 disabled:opacity-70 text-white font-bold py-3 rounded-lg transition-colors flex justify-center items-center"
